$header = '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="1024" android:viewportHeight="1024">'
$created = 0
foreach ($entry in $icons) {
    $parts = $entry -split '\|'
    $name = $parts[0]
    $ring = $parts[1]
    $solid = $parts[2]
    $body = "    " + $header + "`r`n"
    if ($ring) {
        $body += '    <path android:fillColor="#ffffff" android:pathData="' + $ring + '" />' + "`r`n"
    }
    if ($solid) {
        $body += '    <path android:fillColor="#ffffff" android:pathData="' + $solid + '" />' + "`r`n"
    }
    $body += "</vector>`r`n"
    Set-Content -Path (Join-Path $dir ($name + ".xml")) -Value $body -Encoding UTF8 -NoNewline
    $created++
}
Write-Output ("generated " + $created + " icons into " + $dir)
